133	    }
134	
135	    public Integer getNamesakeCount() {
136	        return this.namesakeCount;
137	    }
138	
139	    public void setNamesakeCount(Integer namesakeCount) {
140	        this.namesakeCount = namesakeCount;
141	    }
142	
143	    public Integer getHouseholdSize() {
144	        return this.householdSize;
145	    }
146	
147	    public void setHouseholdSize(Integer householdSize) {
148	        this.householdSize = householdSize;
149	    }
150	
151	    public String getMembershipNumber() {
152	        return this.membershipNumber;
153	    }
154	
155	    public void setMembershipNumber(String membershipNumber) {
156	        this.membershipNumber = membershipNumber;
157	    }
158	
159	    /**
160	     * Whether this owner was created as part of a bulk signup: {@code true} when more
161	     * than 80 owners had already been registered on this owner's registration date at
162	     * the moment it was created, {@code false} otherwise. Captured at creation.
163	     */
164	    public boolean isBulkSignupWarning() {
165	        return this.bulkSignupWarning;
166	    }
167	
168	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
169	        this.bulkSignupWarning = bulkSignupWarning;
170	    }
171	
172	    /**
173	     * The owner's locality: the canonical region derived from the city via the fixed
174	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or
175	     * {@code "UNKNOWN"} for any other city. Derived from stored state, never persisted.
176	     */
177	    public String getLocality() {
178	        return CityLocality.forCity(this.city);
179	    }
180	
181	    /**
182	     * The owner's membership tier: {@code GOLD} when this owner's household had 3 or more
183	     * members at creation ({@code householdSize} is 3 or more); otherwise {@code SILVER}
184	     * when this owner had no namesakes at creation ({@code namesakeCount} is 0) and has an
185	     * email address, and {@code BRONZE} otherwise. Derived from stored state, never
186	     * persisted.
187	     */
188	    public String getMembershipTier() {
189	        if (this.householdSize != null && this.householdSize >= 3) {
190	            return "GOLD";
191	        }
192	        boolean silver = Integer.valueOf(0).equals(this.namesakeCount)
193	            && this.email != null && !this.email.isEmpty();
194	        return silver ? "SILVER" : "BRONZE";
195	    }
196	
197	    protected Set<Pet> getPetsInternal() {
198	        if (this.pets == null) {
199	            this.pets = new HashSet<>();
200	        }
201	        return this.pets;
202	    }
203	
204	    protected void setPetsInternal(Set<Pet> pets) {
205	        this.pets = pets;
206	    }
207	
208	    public List<Pet> getPets() {
209	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
210	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
211	        return Collections.unmodifiableList(sortedPets);
212	    }
213	
214	    public void setPets(List<Pet> pets) {
215	        this.pets = new HashSet<>(pets);
216	    }
217	
218	    public void addPet(Pet pet) {
219	        getPetsInternal().add(pet);
220	        pet.setOwner(this);
221	    }
222	
223	    /**
224	     * Return the Pet with the given name, or null if none found for this Owner.
225	     *
226	     * @param name to test
227	     * @return true if pet name is already in use
228	     */
229	    public Pet getPet(String name) {
230	        return getPet(name, false);
231	    }
232	
233	    /**
234	     * Return the Pet with the given name, or null if none found for this Owner.
235	     *
236	     * @param name to test
237	     * @return true if pet name is already in use
238	     */
239	    public Pet getPet(String name, boolean ignoreNew) {
240	        name = name.toLowerCase();
241	        for (Pet pet : getPetsInternal()) {
242	            if (!ignoreNew || !pet.isNew()) {
243	                String compName = pet.getName();
244	                compName = compName.toLowerCase();
245	                if (compName.equals(name)) {
246	                    return pet;
247	                }
248	            }
249	        }
250	        return null;
251	    }
252	
253	    public Pet getPet(Integer petId) {
254	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
255	    }
256	
257	    @Override
258	    public String toString() {
259	        return new ToStringCreator(this)
260	
261	            .append("id", this.getId())
262	            .append("new", this.isNew())
263	            .append("lastName", this.getLastName())
264	            .append("firstName", this.getFirstName())
265	            .append("address", this.address)
266	            .append("city", this.city)
267	            .append("telephone", this.telephone)
268	            .toString();
269	    }
270	}
