1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the new owner's {@code householdSize}: the number of owners in its household
9	 * (same last name and address, see {@link Households}) once this owner is added — the
10	 * existing household members plus the new owner itself. Runs after {@link BuildOwner} (so
11	 * the entity, its name and normalized address exist) and before {@link SaveOwner} persists
12	 * the count, so the freshly created owner is counted exactly once. A three-or-more member
13	 * household makes the owner {@code GOLD} (see {@link Owner#getMembershipTier()}).
14	 */
15	public class AssignOwnerHouseholdSize {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        int existing = Households.membersOf(ownerRepository, owner.getLastName(), owner.getAddress()).size();
19	        owner.setHouseholdSize(existing + 1);
20	    }
21	}
